TwistExpander_Betelgeuse::TwistExpander_Betelgeuse()
: TwistExpander() {
    mDomainBundleInbuilt.mSeedSalts = kSeedSalts;
    mDomainBundleInbuilt.mSeedConstants = kSeedConstants;
    mDomainBundleEphemeralA.Zero();
    mDomainBundleEphemeralB.Zero();
}

void TwistExpander_Betelgeuse::KDF_A_F(TwistWorkSpace *pWorkSpace,
               std::uint64_t pNonce,
               TwistDomainConstants *pConstants,
               TwistDomainSaltSet *pDomainSaltSet,
               MUTABLE_PARAMS) {
    std::uint8_t *aFireLaneA = pWorkSpace->mFireLaneA;
    std::uint8_t *aFireLaneB = pWorkSpace->mFireLaneB;
    std::uint8_t *aFireLaneC = pWorkSpace->mFireLaneC;
    std::uint8_t *aFireLaneD = pWorkSpace->mFireLaneD;
    std::uint8_t *aShadowLaneA = pWorkSpace->mShadowLaneA;
    std::uint8_t *aShadowLaneB = pWorkSpace->mShadowLaneB;
    std::uint8_t *aShadowLaneC = pWorkSpace->mShadowLaneC;
    std::uint8_t *aShadowLaneD = pWorkSpace->mShadowLaneD;
    std::uint8_t *aVaporLaneA = pWorkSpace->mVaporLaneA;
    std::uint8_t *aVaporLaneB = pWorkSpace->mVaporLaneB;
    std::uint8_t *aVaporLaneC = pWorkSpace->mVaporLaneC;
    std::uint8_t *aVaporLaneD = pWorkSpace->mVaporLaneD;
    std::size_t *aIndexList256A = pWorkSpace->mIndexList256A;
    std::size_t *aIndexList256B = pWorkSpace->mIndexList256B;
    std::size_t *aIndexList256C = pWorkSpace->mIndexList256C;
    std::size_t *aIndexList256D = pWorkSpace->mIndexList256D;

    std::uint64_t aDomainWordMatrixSelectA = pConstants->mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pConstants->mMatrixSelectB;
    std::uint8_t aDomainWordMatrixUnrollA = pConstants->mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pConstants->mMatrixUnrollB;
    std::uint8_t aDomainWordMatrixArgA = pConstants->mMatrixArgA;
    std::uint8_t aDomainWordMatrixArgB = pConstants->mMatrixArgB;
    std::uint8_t aDomainWordMatrixArgC = pConstants->mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pConstants->mMatrixArgD;

    //
    // src: [source, nonce]
    // dst: [$shadow]
    //
    TwistExpander_Betelgeuse_Arx::KDF_A_A_F(PARAMS_KDF);

    //
    // src: [$shadow]
    // dst: [$fire]
    //
    TwistExpander_Betelgeuse_Arx::KDF_A_B_F(PARAMS_KDF);

    //
    // ent: [$shadow]
    // src: [$fire]
    // dst: [$vapor]
    //
    TwistDiffuse::DiffuseWithDomainWords(
        aShadowLaneA, aShadowLaneB, aShadowLaneC, aShadowLaneD, // entropy lanes
        aFireLaneA, aFireLaneB, aFireLaneC, aFireLaneD,  // input lanes
        aVaporLaneA, aVaporLaneB, aVaporLaneC, aVaporLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$vapor]
    // dst: [$kinetic]
    //
    TwistExpander_Betelgeuse_Arx::KDF_A_C_F(PARAMS_KDF);

}

void TwistExpander_Betelgeuse::KDF_B_F(TwistWorkSpace *pWorkSpace,
               std::uint64_t pNonce,
               TwistDomainConstants *pConstants,
               TwistDomainSaltSet *pDomainSaltSet,
               MUTABLE_PARAMS) {
    std::uint8_t *aRunicLaneA = pWorkSpace->mRunicLaneA;
    std::uint8_t *aRunicLaneB = pWorkSpace->mRunicLaneB;
    std::uint8_t *aRunicLaneC = pWorkSpace->mRunicLaneC;
    std::uint8_t *aRunicLaneD = pWorkSpace->mRunicLaneD;
    std::uint8_t *aDivinationLaneA = pWorkSpace->mDivinationLaneA;
    std::uint8_t *aDivinationLaneB = pWorkSpace->mDivinationLaneB;
    std::uint8_t *aDivinationLaneC = pWorkSpace->mDivinationLaneC;
    std::uint8_t *aDivinationLaneD = pWorkSpace->mDivinationLaneD;
    std::uint8_t *aEvocationLaneA = pWorkSpace->mEvocationLaneA;
    std::uint8_t *aEvocationLaneB = pWorkSpace->mEvocationLaneB;
    std::uint8_t *aEvocationLaneC = pWorkSpace->mEvocationLaneC;
    std::uint8_t *aEvocationLaneD = pWorkSpace->mEvocationLaneD;
    std::size_t *aIndexList256A = pWorkSpace->mIndexList256A;
    std::size_t *aIndexList256B = pWorkSpace->mIndexList256B;
    std::size_t *aIndexList256C = pWorkSpace->mIndexList256C;
    std::size_t *aIndexList256D = pWorkSpace->mIndexList256D;

    std::uint64_t aDomainWordMatrixSelectA = pConstants->mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pConstants->mMatrixSelectB;
    std::uint8_t aDomainWordMatrixUnrollA = pConstants->mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pConstants->mMatrixUnrollB;
    std::uint8_t aDomainWordMatrixArgA = pConstants->mMatrixArgA;
    std::uint8_t aDomainWordMatrixArgB = pConstants->mMatrixArgB;
    std::uint8_t aDomainWordMatrixArgC = pConstants->mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pConstants->mMatrixArgD;

    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    TwistExpander_Betelgeuse_Arx::KDF_B_A_F(PARAMS_KDF);

    //
    // src: [$evocation]
    // dst: [$runic]
    //
    TwistExpander_Betelgeuse_Arx::KDF_B_B_F(PARAMS_KDF);

    //
    // ent: [$evocation]
    // src: [$runic]
    // dst: [$divination]
    //
    TwistDiffuse::DiffuseWithDomainWords(
        aEvocationLaneA, aEvocationLaneB, aEvocationLaneC, aEvocationLaneD, // entropy lanes
        aRunicLaneA, aRunicLaneB, aRunicLaneC, aRunicLaneD,  // input lanes
        aDivinationLaneA, aDivinationLaneB, aDivinationLaneC, aDivinationLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$divination]
    // dst: [$abjuration]
    //
    TwistExpander_Betelgeuse_Arx::KDF_B_C_F(PARAMS_KDF);

}

void TwistExpander_Betelgeuse::KDF_C_F(TwistWorkSpace *pWorkSpace,
               std::uint64_t pNonce,
               TwistDomainConstants *pConstants,
               TwistDomainSaltSet *pDomainSaltSet,
               MUTABLE_PARAMS) {
    std::uint8_t *aEarthLaneA = pWorkSpace->mEarthLaneA;
    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint8_t *aAetherLaneA = pWorkSpace->mAetherLaneA;
    std::uint8_t *aAetherLaneB = pWorkSpace->mAetherLaneB;
    std::uint8_t *aAetherLaneC = pWorkSpace->mAetherLaneC;
    std::uint8_t *aAetherLaneD = pWorkSpace->mAetherLaneD;
    std::uint8_t *aLunarLaneA = pWorkSpace->mLunarLaneA;
    std::uint8_t *aLunarLaneB = pWorkSpace->mLunarLaneB;
    std::uint8_t *aLunarLaneC = pWorkSpace->mLunarLaneC;
    std::uint8_t *aLunarLaneD = pWorkSpace->mLunarLaneD;
    std::size_t *aIndexList256A = pWorkSpace->mIndexList256A;
    std::size_t *aIndexList256B = pWorkSpace->mIndexList256B;
    std::size_t *aIndexList256C = pWorkSpace->mIndexList256C;
    std::size_t *aIndexList256D = pWorkSpace->mIndexList256D;

    std::uint64_t aDomainWordMatrixSelectA = pConstants->mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pConstants->mMatrixSelectB;
    std::uint8_t aDomainWordMatrixUnrollA = pConstants->mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pConstants->mMatrixUnrollB;
    std::uint8_t aDomainWordMatrixArgA = pConstants->mMatrixArgA;
    std::uint8_t aDomainWordMatrixArgB = pConstants->mMatrixArgB;
    std::uint8_t aDomainWordMatrixArgC = pConstants->mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pConstants->mMatrixArgD;

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    TwistExpander_Betelgeuse_Arx::KDF_C_A_F(PARAMS_KDF);

    //
    // src: [$aether]
    // dst: [$lunar]
    //
    TwistExpander_Betelgeuse_Arx::KDF_C_B_F(PARAMS_KDF);

    //
    // ent: [$aether]
    // src: [$lunar]
    // dst: [$earth]
    //
    TwistDiffuse::DiffuseWithDomainWords(
        aAetherLaneA, aAetherLaneB, aAetherLaneC, aAetherLaneD, // entropy lanes
        aLunarLaneA, aLunarLaneB, aLunarLaneC, aLunarLaneD,  // input lanes
        aEarthLaneA, aEarthLaneB, aEarthLaneC, aEarthLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$earth]
    // dst: [$crystal]
    //
    TwistExpander_Betelgeuse_Arx::KDF_C_C_F(PARAMS_KDF);

}

void TwistExpander_Betelgeuse::Seed(TwistWorkSpace *pWorkSpace,
                                 std::uint64_t pNonce,
                                 std::uint8_t *pPassword,
                                 std::size_t pPasswordByteLength,
                                 std::uint8_t *pDestination,
                                 MUTABLE_PARAMS) {
    if ((pWorkSpace == nullptr) || (pDestination == nullptr) ||
        MUTABLE_PARAMS_ARE_NULL) { return; }

    UnrollPassword(pWorkSpace->mSourceLane, pPassword, pPasswordByteLength);
    UnrollNonce(pWorkSpace->mNonceLane, pNonce);
    mDomainBundleInbuilt.mSeedSalts = kSeedSalts;
    mDomainBundleInbuilt.mSeedConstants = kSeedConstants;
    mDomainBundleEphemeralA.Zero();
    mDomainBundleEphemeralB.Zero();
    pWorkSpace->mDomainBundle.Zero();
    std::uint8_t *aSpiritLaneA = pWorkSpace->mSpiritLaneA;
    std::uint8_t *aSpiritLaneB = pWorkSpace->mSpiritLaneB;
    std::uint8_t *aSpiritLaneC = pWorkSpace->mSpiritLaneC;
    std::uint8_t *aSpiritLaneD = pWorkSpace->mSpiritLaneD;
    std::uint8_t *aFireLaneA = pWorkSpace->mFireLaneA;
    std::uint8_t *aFireLaneB = pWorkSpace->mFireLaneB;
    std::uint8_t *aFireLaneC = pWorkSpace->mFireLaneC;
    std::uint8_t *aFireLaneD = pWorkSpace->mFireLaneD;
    std::uint8_t *aRainbowLaneA = pWorkSpace->mRainbowLaneA;
    std::uint8_t *aRainbowLaneB = pWorkSpace->mRainbowLaneB;
    std::uint8_t *aRainbowLaneC = pWorkSpace->mRainbowLaneC;
    std::uint8_t *aRainbowLaneD = pWorkSpace->mRainbowLaneD;
    std::uint8_t *aEarthLaneA = pWorkSpace->mEarthLaneA;
    std::uint8_t *aEarthLaneB = pWorkSpace->mEarthLaneB;
    std::uint8_t *aEarthLaneC = pWorkSpace->mEarthLaneC;
    std::uint8_t *aEarthLaneD = pWorkSpace->mEarthLaneD;
    std::uint8_t *aWindLaneA = pWorkSpace->mWindLaneA;
    std::uint8_t *aWindLaneB = pWorkSpace->mWindLaneB;
    std::uint8_t *aWindLaneC = pWorkSpace->mWindLaneC;
    std::uint8_t *aWindLaneD = pWorkSpace->mWindLaneD;
    std::uint8_t *aLightningLaneA = pWorkSpace->mLightningLaneA;
    std::uint8_t *aLightningLaneB = pWorkSpace->mLightningLaneB;
    std::uint8_t *aLightningLaneC = pWorkSpace->mLightningLaneC;
    std::uint8_t *aLightningLaneD = pWorkSpace->mLightningLaneD;
    std::uint8_t *aShadowLaneA = pWorkSpace->mShadowLaneA;
    std::uint8_t *aShadowLaneB = pWorkSpace->mShadowLaneB;
    std::uint8_t *aShadowLaneC = pWorkSpace->mShadowLaneC;
    std::uint8_t *aShadowLaneD = pWorkSpace->mShadowLaneD;
    std::uint8_t *aCrystalLaneA = pWorkSpace->mCrystalLaneA;
    std::uint8_t *aCrystalLaneB = pWorkSpace->mCrystalLaneB;
    std::uint8_t *aCrystalLaneC = pWorkSpace->mCrystalLaneC;
    std::uint8_t *aCrystalLaneD = pWorkSpace->mCrystalLaneD;
    std::uint8_t *aAetherLaneA = pWorkSpace->mAetherLaneA;
    std::uint8_t *aAetherLaneB = pWorkSpace->mAetherLaneB;
    std::uint8_t *aAetherLaneC = pWorkSpace->mAetherLaneC;
    std::uint8_t *aAetherLaneD = pWorkSpace->mAetherLaneD;
    std::uint8_t *aVaporLaneA = pWorkSpace->mVaporLaneA;
    std::uint8_t *aVaporLaneB = pWorkSpace->mVaporLaneB;
    std::uint8_t *aVaporLaneC = pWorkSpace->mVaporLaneC;
    std::uint8_t *aVaporLaneD = pWorkSpace->mVaporLaneD;
    std::uint8_t *aKineticLaneA = pWorkSpace->mKineticLaneA;
    std::uint8_t *aKineticLaneB = pWorkSpace->mKineticLaneB;
    std::uint8_t *aKineticLaneC = pWorkSpace->mKineticLaneC;
    std::uint8_t *aKineticLaneD = pWorkSpace->mKineticLaneD;
    std::uint8_t *aSonicLaneA = pWorkSpace->mSonicLaneA;
    std::uint8_t *aSonicLaneB = pWorkSpace->mSonicLaneB;
    std::uint8_t *aSonicLaneC = pWorkSpace->mSonicLaneC;
    std::uint8_t *aSonicLaneD = pWorkSpace->mSonicLaneD;
    std::uint8_t *aPlanarLaneA = pWorkSpace->mPlanarLaneA;
    std::uint8_t *aPlanarLaneB = pWorkSpace->mPlanarLaneB;
    std::uint8_t *aPlanarLaneC = pWorkSpace->mPlanarLaneC;
    std::uint8_t *aPlanarLaneD = pWorkSpace->mPlanarLaneD;
    std::uint8_t *aFrostLaneA = pWorkSpace->mFrostLaneA;
    std::uint8_t *aFrostLaneB = pWorkSpace->mFrostLaneB;
    std::uint8_t *aFrostLaneC = pWorkSpace->mFrostLaneC;
    std::uint8_t *aFrostLaneD = pWorkSpace->mFrostLaneD;
    std::uint8_t *aLunarLaneA = pWorkSpace->mLunarLaneA;
    std::uint8_t *aLunarLaneB = pWorkSpace->mLunarLaneB;
    std::uint8_t *aLunarLaneC = pWorkSpace->mLunarLaneC;
    std::uint8_t *aLunarLaneD = pWorkSpace->mLunarLaneD;
    std::uint8_t *aRunicLaneA = pWorkSpace->mRunicLaneA;
    std::uint8_t *aRunicLaneB = pWorkSpace->mRunicLaneB;
    std::uint8_t *aRunicLaneC = pWorkSpace->mRunicLaneC;
    std::uint8_t *aRunicLaneD = pWorkSpace->mRunicLaneD;
    std::uint8_t *aGloomLaneA = pWorkSpace->mGloomLaneA;
    std::uint8_t *aGloomLaneB = pWorkSpace->mGloomLaneB;
    std::uint8_t *aGloomLaneC = pWorkSpace->mGloomLaneC;
    std::uint8_t *aGloomLaneD = pWorkSpace->mGloomLaneD;
    std::uint8_t *aAbjurationLaneA = pWorkSpace->mAbjurationLaneA;
    std::uint8_t *aAbjurationLaneB = pWorkSpace->mAbjurationLaneB;
    std::uint8_t *aAbjurationLaneC = pWorkSpace->mAbjurationLaneC;
    std::uint8_t *aAbjurationLaneD = pWorkSpace->mAbjurationLaneD;
    std::uint8_t *aDivinationLaneA = pWorkSpace->mDivinationLaneA;
    std::uint8_t *aDivinationLaneB = pWorkSpace->mDivinationLaneB;
    std::uint8_t *aDivinationLaneC = pWorkSpace->mDivinationLaneC;
    std::uint8_t *aDivinationLaneD = pWorkSpace->mDivinationLaneD;
    std::uint8_t *aEvocationLaneA = pWorkSpace->mEvocationLaneA;
    std::uint8_t *aEvocationLaneB = pWorkSpace->mEvocationLaneB;
    std::uint8_t *aEvocationLaneC = pWorkSpace->mEvocationLaneC;
    std::uint8_t *aEvocationLaneD = pWorkSpace->mEvocationLaneD;
    std::uint8_t *aStasisLaneA = pWorkSpace->mStasisLaneA;
    std::uint8_t *aStasisLaneB = pWorkSpace->mStasisLaneB;
    std::uint8_t *aStasisLaneC = pWorkSpace->mStasisLaneC;
    std::uint8_t *aAlchemyLaneA = pWorkSpace->mAlchemyLaneA;
    std::uint8_t *aAlchemyLaneB = pWorkSpace->mAlchemyLaneB;
    std::uint8_t *aAlchemyLaneC = pWorkSpace->mAlchemyLaneC;
    std::uint8_t *aAlchemyLaneD = pWorkSpace->mAlchemyLaneD;
    std::uint8_t *aAuguryLaneA = pWorkSpace->mAuguryLaneA;
    std::uint8_t *aAuguryLaneB = pWorkSpace->mAuguryLaneB;
    std::uint8_t *aAuguryLaneC = pWorkSpace->mAuguryLaneC;
    std::uint8_t *aAuguryLaneD = pWorkSpace->mAuguryLaneD;
    std::uint8_t *aPsychicLaneA = pWorkSpace->mPsychicLaneA;
    std::uint8_t *aPsychicLaneB = pWorkSpace->mPsychicLaneB;
    std::uint8_t *aPsychicLaneC = pWorkSpace->mPsychicLaneC;
    std::uint8_t *aPsychicLaneD = pWorkSpace->mPsychicLaneD;
    std::uint8_t *aVoodooLaneA = pWorkSpace->mVoodooLaneA;
    std::uint8_t *aVoodooLaneB = pWorkSpace->mVoodooLaneB;
    std::uint8_t *aVoodooLaneC = pWorkSpace->mVoodooLaneC;
    std::uint8_t *aVoodooLaneD = pWorkSpace->mVoodooLaneD;
    std::uint8_t *aIceLaneA = pWorkSpace->mIceLaneA;
    std::uint8_t *aIceLaneB = pWorkSpace->mIceLaneB;
    std::uint8_t *aIceLaneC = pWorkSpace->mIceLaneC;
    std::uint8_t *aIceLaneD = pWorkSpace->mIceLaneD;
    std::size_t *aIndexList256A = pWorkSpace->mIndexList256A;
    std::size_t *aIndexList256B = pWorkSpace->mIndexList256B;
    std::size_t *aIndexList256C = pWorkSpace->mIndexList256C;
    std::size_t *aIndexList256D = pWorkSpace->mIndexList256D;

    std::uint64_t aIngress = *pIngress + 0x8D67CA8611E50B42ULL;
    std::uint64_t aCarry = *pCarry + 0xD5915B96F5A6E24DULL;
    std::uint64_t aWandererA = *pWandererA + 0x3A5CBAD105E5F5D4ULL;
    std::uint64_t aWandererB = *pWandererB + 0xB0AB54066725B490ULL;
    std::uint64_t aWandererC = *pWandererC + 0x61A14E2655C244CAULL;
    std::uint64_t aWandererD = *pWandererD + 0x78081BAE48C6ABCCULL;
    std::uint64_t aWandererE = *pWandererE + 0x265781A7C9B8940CULL;
    std::uint64_t aWandererF = *pWandererF + 0x55B610387548EE9FULL;
    std::uint64_t aWandererG = *pWandererG + 0x5F773AE36864C872ULL;
    std::uint64_t aWandererH = *pWandererH + 0xBFADA39A5F82C0C2ULL;
    std::uint64_t aWandererI = *pWandererI + 0xAF35742C28A69490ULL;
    std::uint64_t aWandererJ = *pWandererJ + 0xCB122DC33DBBD7B9ULL;
    std::uint64_t aWandererK = *pWandererK + 0xFBA0FE47B8B9359EULL;


    ////////////////////////////////////////////////////////
    //
    // Seed-domain secret material derivation.
    //
    KDF_A_F(pWorkSpace, pNonce, &(mDomainBundleInbuilt.mSeedConstants), &(mDomainBundleInbuilt.mSeedSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aKineticLaneB, aKineticLaneC, aKineticLaneD, aKineticLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralA.mSeedSalts,
                    &(mDomainBundleEphemeralA.mSeedConstants));

    KDF_B_F(pWorkSpace, pNonce, &(mDomainBundleEphemeralA.mSeedConstants), &(mDomainBundleEphemeralA.mSeedSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, aAbjurationLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &mDomainBundleEphemeralB.mSeedSalts,
                    &(mDomainBundleEphemeralB.mSeedConstants));

    KDF_C_F(pWorkSpace, pNonce, &(mDomainBundleEphemeralB.mSeedConstants), &(mDomainBundleEphemeralB.mSeedSalts), ARX_STATE_VARS);

    TwistFarm::Farm(
                    aCrystalLaneB, aCrystalLaneC, aCrystalLaneD, aCrystalLaneA, // farm lanes
                    aStasisLaneA, aStasisLaneB, aStasisLaneC, // temp/fold lanes
                    &pWorkSpace->mDomainBundle.mSeedSalts,
                    &(pWorkSpace->mDomainBundle.mSeedConstants));
    //
    ////////////////////////////////////////////////////////

    std::uint64_t aDomainWordMatrixSelectA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectA;
    std::uint64_t aDomainWordMatrixSelectB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixSelectB;

    std::uint8_t aDomainWordMatrixUnrollA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixUnrollA;
    std::uint8_t aDomainWordMatrixUnrollB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixUnrollB;

    std::uint8_t aDomainWordMatrixArgA = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgA;
    std::uint8_t aDomainWordMatrixArgB = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgB;
    std::uint8_t aDomainWordMatrixArgC = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgC;
    std::uint8_t aDomainWordMatrixArgD = pWorkSpace->mDomainBundle.mSeedConstants.mMatrixArgD;

    ////////////////////////////////////////////////////////
    //
    // Main seed loops
    //
    // src: [source, nonce]
    // dst: [$ice]
    //
    TwistExpander_Betelgeuse_Arx::SEED_A(PARAMS_SEED);

    //
    // src: [$ice]
    // dst: [$rainbow]
    //
    TwistExpander_Betelgeuse_Arx::SEED_B(PARAMS_SEED);

    //
    // ent: [$ice]
    // src: [$rainbow]
    // dst: [$alchemy]
    //
    TwistDiffuse::DiffuseWithDomainWords(
        aIceLaneA, aIceLaneB, aIceLaneC, aIceLaneD, // entropy lanes
        aRainbowLaneA, aRainbowLaneB, aRainbowLaneC, aRainbowLaneD,  // input lanes
        aAlchemyLaneA, aAlchemyLaneB, aAlchemyLaneC, aAlchemyLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$alchemy]
    // dst: [$augury]
    //
    TwistExpander_Betelgeuse_Arx::SEED_C(PARAMS_SEED);

    //
    // src: [$augury]
    // dst: [$spirit]
    //
    TwistExpander_Betelgeuse_Arx::SEED_D(PARAMS_SEED);

    //
    // ent: [$augury]
    // src: [$spirit]
    // dst: [$divination]
    //
    TwistDiffuse::DiffuseWithDomainWords(
        aAuguryLaneA, aAuguryLaneB, aAuguryLaneC, aAuguryLaneD, // entropy lanes
        aSpiritLaneA, aSpiritLaneB, aSpiritLaneC, aSpiritLaneD,  // input lanes
        aDivinationLaneA, aDivinationLaneB, aDivinationLaneC, aDivinationLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$divination]
    // dst: [$psychic]
    //
    TwistExpander_Betelgeuse_Arx::SEED_E(PARAMS_SEED);

    //
    // src: [$psychic]
    // dst: [$voodoo]
    //
    TwistExpander_Betelgeuse_Arx::SEED_F(PARAMS_SEED);

    //
    // ent: [$psychic]
    // src: [$voodoo]
    // dst: [$vapor]
    //
    TwistDiffuse::DiffuseWithDomainWords(
        aPsychicLaneA, aPsychicLaneB, aPsychicLaneC, aPsychicLaneD, // entropy lanes
        aVoodooLaneA, aVoodooLaneB, aVoodooLaneC, aVoodooLaneD,  // input lanes
        aVaporLaneA, aVaporLaneB, aVaporLaneC, aVaporLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$vapor]
    // dst: [$sonic]
    //
    TwistExpander_Betelgeuse_Arx::SEED_G(PARAMS_SEED);

    //
    // src: [$sonic]
    // dst: [$planar]
    //
    TwistExpander_Betelgeuse_Arx::SEED_H(PARAMS_SEED);

    //
    // ent: [$sonic]
    // src: [$planar]
    // dst: [$frost]
    //
    TwistDiffuse::DiffuseWithDomainWords(
        aSonicLaneA, aSonicLaneB, aSonicLaneC, aSonicLaneD, // entropy lanes
        aPlanarLaneA, aPlanarLaneB, aPlanarLaneC, aPlanarLaneD,  // input lanes
        aFrostLaneA, aFrostLaneB, aFrostLaneC, aFrostLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$frost]
    // dst: [$gloom]
    //
    TwistExpander_Betelgeuse_Arx::SEED_I(PARAMS_SEED);

    //
    // src: [$gloom]
    // dst: [$lightning]
    //
    TwistExpander_Betelgeuse_Arx::SEED_J(PARAMS_SEED);

    //
    // ent: [$gloom]
    // src: [$lightning]
    // dst: [$wind]
    //
    TwistDiffuse::DiffuseWithDomainWords(
        aGloomLaneA, aGloomLaneB, aGloomLaneC, aGloomLaneD, // entropy lanes
        aLightningLaneA, aLightningLaneB, aLightningLaneC, aLightningLaneD,  // input lanes
        aWindLaneA, aWindLaneB, aWindLaneC, aWindLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$wind]
    // dst: [$shadow]
    //
    TwistExpander_Betelgeuse_Arx::SEED_K(PARAMS_SEED);

    //
    // src: [$shadow]
    // dst: [$fire]
    //
    TwistExpander_Betelgeuse_Arx::SEED_L(PARAMS_SEED);

    //
    // ent: [$shadow]
    // src: [$fire]
    // dst: [$kinetic]
    //
    TwistDiffuse::DiffuseWithDomainWords(
        aShadowLaneA, aShadowLaneB, aShadowLaneC, aShadowLaneD, // entropy lanes
        aFireLaneA, aFireLaneB, aFireLaneC, aFireLaneD,  // input lanes
        aKineticLaneA, aKineticLaneB, aKineticLaneC, aKineticLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$kinetic]
    // dst: [$evocation]
    //
    TwistExpander_Betelgeuse_Arx::SEED_M(PARAMS_SEED);

    //
    // src: [$evocation]
    // dst: [$runic]
    //
    TwistExpander_Betelgeuse_Arx::SEED_N(PARAMS_SEED);

    //
    // ent: [$evocation]
    // src: [$runic]
    // dst: [$abjuration]
    //
    TwistDiffuse::DiffuseWithDomainWords(
        aEvocationLaneA, aEvocationLaneB, aEvocationLaneC, aEvocationLaneD, // entropy lanes
        aRunicLaneA, aRunicLaneB, aRunicLaneC, aRunicLaneD,  // input lanes
        aAbjurationLaneA, aAbjurationLaneB, aAbjurationLaneC, aAbjurationLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$abjuration]
    // dst: [$aether]
    //
    TwistExpander_Betelgeuse_Arx::SEED_O(PARAMS_SEED);

    //
    // src: [$aether]
    // dst: [$lunar]
    //
    TwistExpander_Betelgeuse_Arx::SEED_P(PARAMS_SEED);

    //
    // ent: [$aether]
    // src: [$lunar]
    // dst: [$earth]
    //
    TwistDiffuse::DiffuseWithDomainWords(
        aAetherLaneA, aAetherLaneB, aAetherLaneC, aAetherLaneD, // entropy lanes
        aLunarLaneA, aLunarLaneB, aLunarLaneC, aLunarLaneD,  // input lanes
        aEarthLaneA, aEarthLaneB, aEarthLaneC, aEarthLaneD, // output lanes
        aIndexList256A, aIndexList256B, aIndexList256C, aIndexList256D,
        &mMatrix,
        aDomainWordMatrixSelectA, aDomainWordMatrixSelectB,
        aDomainWordMatrixUnrollA, aDomainWordMatrixUnrollB,
        aDomainWordMatrixArgA, aDomainWordMatrixArgB, aDomainWordMatrixArgC, aDomainWordMatrixArgD);

    //
    // src: [$earth]
    // dst: [$crystal]
    //
    TwistExpander_Betelgeuse_Arx::SEED_Q(PARAMS_SEED);
    //
    ////////////////////////////////////////////////////////

    ////////////////////////////////////////////////////////
    //
    // Folding main seed loops into destination
    //
    TwistSquash::SquashB(pWorkSpace->mCrystalLaneA, pWorkSpace->mCrystalLaneB, pWorkSpace->mCrystalLaneC, pWorkSpace->mCrystalLaneD, pDestination);
    //
    ////////////////////////////////////////////////////////

    pWorkSpace->Zero_PostSeed();

    Zero_PostSeed();

    //
    ////////////////////////////////////////////////////////
    
    WRITE_OUT_MUTABLE_PARAMS;
    
}

